/**
 * RT-1463 FROZEN REFERENCE — the exact SQL text, as on origin/main da17c0d3, of the two statements the catalog split
 * may only re-compose (owner decision, RT-1463 comment 18321): the posting feed page query (one snapshot decides the
 * holds and the Connector cursor, RT-418) and the operator resolution freeze (`posting-resolution.writer.ts`, an
 * INSERT ... SELECT that writes, so it cannot be run twice and compared). `posting-sql-frozen.unit.spec.ts` fails when
 * the text Postgres receives differs by one character. Test-only; do not edit. Delete with the legacy directory once
 * RT-1463 is closed.
 */
export const FROZEN_POSTING_FEED_PAGE_SQL = "WITH ts AS (\n             SELECT ($4::boolean AND COALESCE(\n                       (SELECT tracked_selling_enabled FROM tenant_inventory_settings\n                         WHERE tenant_id = $5::uuid), false)) AS on_\n           )\n           SELECT id, kind, sale_id, source_ref_id, source_system, external_id,\n                  payload_hash, sequence::text AS sequence,\n                  current_resolution_version, (SELECT on_ FROM ts) AS tracking_on\n             FROM erpnext_posting_status\n            WHERE status = 'pending'\n              AND ($1::bigint IS NULL OR sequence > $1::bigint)\n              AND NOT EXISTS (\n                SELECT 1 FROM tenant_access_entitlements tae\n                 WHERE tae.tenant_id = $5::uuid AND tae.state = 'restricted')\n              AND NOT EXISTS (\n                SELECT 1 FROM sales s\n                 WHERE s.id = erpnext_posting_status.sale_id\n                   AND s.responsibility_count > 0\n                   AND (erpnext_posting_status.kind = 'reversal'\n                        OR NOT $3::boolean\n                        OR (SELECT count(*) FROM sale_responsibilities sr\n                             WHERE sr.sale_id = s.id) <> s.responsibility_count\n                        OR NOT (CASE\n                          WHEN erpnext_posting_status.current_resolution_version IS NOT NULL THEN EXISTS (\n                            SELECT 1 FROM erpnext_posting_resolution fr\n                             WHERE fr.intent_id = erpnext_posting_status.id\n                               AND fr.resolution_version = erpnext_posting_status.current_resolution_version\n                               AND fr.payer_external_ref ~ '[^[:space:]]')\n                          ELSE NOT EXISTS (\n                            SELECT 1 FROM sale_responsibilities sr\n                              JOIN payer_account p ON p.id = sr.payer_id\n                             WHERE sr.sale_id = s.id\n                               AND (p.external_ref IS NULL OR p.external_ref !~ '[^[:space:]]'))\n                        END)\n                        OR EXISTS (SELECT 1 FROM sale_voids v WHERE v.sale_id = s.id)\n                        OR EXISTS (SELECT 1 FROM sale_refunds f WHERE f.sale_id = s.id)\n                        OR EXISTS (SELECT 1 FROM sale_returns r WHERE r.sale_id = s.id)))\n              AND NOT EXISTS (\n                SELECT 1 FROM sale_lines tsl\n                  LEFT JOIN erpnext_posting_resolution tr\n                    ON tr.intent_id = erpnext_posting_status.id\n                   AND tr.resolution_version = erpnext_posting_status.current_resolution_version\n                   AND tr.sale_line_id = tsl.id\n                 WHERE tsl.sale_id = erpnext_posting_status.sale_id\n                   AND ((tr.tracking_identity_id IS NOT NULL\n                         AND (tr.erp_hold_cause IS NOT NULL OR NOT (SELECT on_ FROM ts)))\n                        OR (erpnext_posting_status.kind = 'sale_post'\n                            AND tr.tracking_mode IS NULL AND tsl.tracking_class IS NOT NULL)))\n            ORDER BY erpnext_posting_status.sequence\n            LIMIT $2";

/** `freezeOperatorResolution` for a reversal: next version, copy from the sale, then resolve when nothing was copied. */
export const FROZEN_FREEZE_REVERSAL_SQL: readonly string[] = [
  "SELECT COALESCE(MAX(resolution_version), 0) + 1 AS v\n         FROM erpnext_posting_resolution WHERE intent_id = $1",
  "INSERT INTO erpnext_posting_resolution\n           (tenant_id, intent_id, resolution_version, sale_line_id,\n            erpnext_item_ref, item_map_id, warehouse_ref, warehouse_map_id, resolved_by,\n            payer_external_ref, tracking_mode, tracking_identity_id, erpnext_batch_ref, erp_hold_cause)\n         SELECT $1, $2, $3, r.sale_line_id,\n                r.erpnext_item_ref, r.item_map_id, r.warehouse_ref, r.warehouse_map_id, 'operator',\n                r.payer_external_ref, r.tracking_mode, r.tracking_identity_id,\n                r.erpnext_batch_ref, r.erp_hold_cause\n           FROM erpnext_posting_status sp\n           JOIN erpnext_posting_resolution r\n             ON r.intent_id = sp.id AND r.resolution_version = sp.current_resolution_version\n          WHERE sp.tenant_id = $1 AND sp.kind = 'sale_post'\n            AND sp.sale_id = $4 AND sp.source_ref_id = $4",
  "INSERT INTO erpnext_posting_resolution\n           (tenant_id, intent_id, resolution_version, sale_line_id,\n            erpnext_item_ref, item_map_id, warehouse_ref, warehouse_map_id, resolved_by,\n            payer_external_ref, tracking_mode, tracking_identity_id, erpnext_batch_ref, erp_hold_cause)\n         SELECT $1, $2, $3, sl.id, m.erpnext_item_ref, m.id,\n                w.erpnext_warehouse_ref, w.id, 'operator',\n                (SELECT p.external_ref\n                   FROM sale_responsibilities sr\n                   JOIN payer_account p ON p.id = sr.payer_id\n                  WHERE sr.sale_id = $4\n                  ORDER BY sr.sequence LIMIT 1),\n                trk.tracking_mode, trk.tracking_identity_id, trk.erpnext_batch_ref, trk.erp_hold_cause\n           FROM sale_lines sl\n           JOIN erpnext_warehouse_map w\n             ON w.store_id = $5 AND w.purpose = 'stock' AND w.retired_at IS NULL\n           JOIN erpnext_item_map m\n             ON m.tenant_product_id = sl.tenant_product_ref\n            AND m.state = 'confirmed' AND m.retired_at IS NULL\n           LEFT JOIN LATERAL (\n      SELECT x.tracking_mode,\n             x.identity_id AS tracking_identity_id,\n             em.erpnext_ref AS erpnext_batch_ref,\n             CASE WHEN x.identity_id IS NULL THEN NULL\n                  WHEN EXISTS (\n                    SELECT 1 FROM sale_line_findings f\n                     WHERE f.sale_line_id = sl.id AND f.tenant_id = sl.tenant_id\n                       AND f.kind = 'erp_intent_held' AND f.cause = 'expired') THEN 'expired'\n                  WHEN em.erpnext_ref IS NULL THEN 'edge_map_missing'\n             END AS erp_hold_cause\n        FROM (SELECT tp.tracking_mode,\n                     CASE WHEN tp.tracking_mode <> 'batch' THEN NULL\n                          WHEN sl.tracking_class IN ('valid', 'flagged') THEN (\n                            SELECT ti.id FROM tracking_identities ti\n                             WHERE ti.id = sl.tracking_identity_id\n                               AND ti.tenant_product_ref = sl.tenant_product_ref\n                               AND ti.tenant_id = sl.tenant_id)\n                          WHEN sl.tracking_class = 'unresolved' THEN (\n                            SELECT bi.id FROM tracking_resolution_lines rl\n                              JOIN tracking_identities bi\n                                ON bi.id = rl.tracking_identity_id\n                               AND bi.tenant_product_ref = sl.tenant_product_ref\n                               AND bi.tenant_id = rl.tenant_id\n                             WHERE rl.sale_line_id = sl.id AND rl.tenant_id = sl.tenant_id)\n                     END AS identity_id\n                FROM tenant_products tp\n               WHERE tp.id = sl.tenant_product_ref) x\n        LEFT JOIN erpnext_tracking_map em\n          ON em.tracking_identity_id = x.identity_id AND em.kind = 'batch'\n    ) trk ON true\n          WHERE sl.sale_id = $4\n            AND NOT EXISTS (\n              SELECT 1 FROM sale_lines ul\n                LEFT JOIN erpnext_item_map um\n                  ON um.tenant_product_id = ul.tenant_product_ref\n                 AND um.state = 'confirmed' AND um.retired_at IS NULL\n               WHERE ul.sale_id = $4\n                 AND (ul.tenant_product_ref IS NULL OR um.id IS NULL))"
];

/** `freezeOperatorResolution` for a sale_post: next version, then resolve. */
export const FROZEN_FREEZE_SALE_SQL: readonly string[] = [
  "SELECT COALESCE(MAX(resolution_version), 0) + 1 AS v\n         FROM erpnext_posting_resolution WHERE intent_id = $1",
  "INSERT INTO erpnext_posting_resolution\n           (tenant_id, intent_id, resolution_version, sale_line_id,\n            erpnext_item_ref, item_map_id, warehouse_ref, warehouse_map_id, resolved_by,\n            payer_external_ref, tracking_mode, tracking_identity_id, erpnext_batch_ref, erp_hold_cause)\n         SELECT $1, $2, $3, sl.id, m.erpnext_item_ref, m.id,\n                w.erpnext_warehouse_ref, w.id, 'operator',\n                (SELECT p.external_ref\n                   FROM sale_responsibilities sr\n                   JOIN payer_account p ON p.id = sr.payer_id\n                  WHERE sr.sale_id = $4\n                  ORDER BY sr.sequence LIMIT 1),\n                trk.tracking_mode, trk.tracking_identity_id, trk.erpnext_batch_ref, trk.erp_hold_cause\n           FROM sale_lines sl\n           JOIN erpnext_warehouse_map w\n             ON w.store_id = $5 AND w.purpose = 'stock' AND w.retired_at IS NULL\n           JOIN erpnext_item_map m\n             ON m.tenant_product_id = sl.tenant_product_ref\n            AND m.state = 'confirmed' AND m.retired_at IS NULL\n           LEFT JOIN LATERAL (\n      SELECT x.tracking_mode,\n             x.identity_id AS tracking_identity_id,\n             em.erpnext_ref AS erpnext_batch_ref,\n             CASE WHEN x.identity_id IS NULL THEN NULL\n                  WHEN EXISTS (\n                    SELECT 1 FROM sale_line_findings f\n                     WHERE f.sale_line_id = sl.id AND f.tenant_id = sl.tenant_id\n                       AND f.kind = 'erp_intent_held' AND f.cause = 'expired') THEN 'expired'\n                  WHEN em.erpnext_ref IS NULL THEN 'edge_map_missing'\n             END AS erp_hold_cause\n        FROM (SELECT tp.tracking_mode,\n                     CASE WHEN tp.tracking_mode <> 'batch' THEN NULL\n                          WHEN sl.tracking_class IN ('valid', 'flagged') THEN (\n                            SELECT ti.id FROM tracking_identities ti\n                             WHERE ti.id = sl.tracking_identity_id\n                               AND ti.tenant_product_ref = sl.tenant_product_ref\n                               AND ti.tenant_id = sl.tenant_id)\n                          WHEN sl.tracking_class = 'unresolved' THEN (\n                            SELECT bi.id FROM tracking_resolution_lines rl\n                              JOIN tracking_identities bi\n                                ON bi.id = rl.tracking_identity_id\n                               AND bi.tenant_product_ref = sl.tenant_product_ref\n                               AND bi.tenant_id = rl.tenant_id\n                             WHERE rl.sale_line_id = sl.id AND rl.tenant_id = sl.tenant_id)\n                     END AS identity_id\n                FROM tenant_products tp\n               WHERE tp.id = sl.tenant_product_ref) x\n        LEFT JOIN erpnext_tracking_map em\n          ON em.tracking_identity_id = x.identity_id AND em.kind = 'batch'\n    ) trk ON true\n          WHERE sl.sale_id = $4\n            AND NOT EXISTS (\n              SELECT 1 FROM sale_lines ul\n                LEFT JOIN erpnext_item_map um\n                  ON um.tenant_product_id = ul.tenant_product_ref\n                 AND um.state = 'confirmed' AND um.retired_at IS NULL\n               WHERE ul.sale_id = $4\n                 AND (ul.tenant_product_ref IS NULL OR um.id IS NULL))"
];
